+// qaObservationDeadline delays only the first QA build watcher so a
+// provider re-offer at its five-minute lease can arrive before we nack.
+// The original token still expires at spawnDeadline and cannot start a runner.
+func qaObservationDeadline(claims claudecode.WorkOrderClaims, budget time.Duration, now time.Time, pool, attempt string) time.Time {
+	deadline := spawnDeadline(claims, budget, now)
+	if pool == "qa-claude" && attempt == "0" {
+		return deadline.Add(time.Minute)
+	}
+	return deadline
+}
