+func TestQAObservationDeadline(t *testing.T) {
+	t.Parallel()
+
+	issued := time.Now().UTC().Truncate(time.Second)
+	claims := dispatchClaims(issued)
+	base := spawnDeadline(claims, 5*time.Minute, issued)
+	for _, tc := range []struct {
+		name    string
+		pool    string
+		attempt string
+		want    time.Time
+	}{
+		{name: "first QA attempt", pool: "qa-claude", attempt: "0", want: base.Add(time.Minute)},
+		{name: "redelivery", pool: "qa-claude", attempt: "1", want: base},
+		{name: "other pool", pool: "other", attempt: "0", want: base},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			t.Parallel()
+			require.Equal(t, tc.want, qaObservationDeadline(claims, 5*time.Minute, issued, tc.pool, tc.attempt))
+		})
+	}
+}
